document.addEventListener('DOMContentLoaded', () => {
  // Select all FAQ trigger buttons
  const triggers = document.querySelectorAll('.faq-trigger[aria-expanded]');

  triggers.forEach((btn) => {
    // The panel is the next sibling element of the heading containing the button
    const heading = btn.closest('h2');
    const panel = heading.nextElementSibling;

    // Check to ensure the next element is indeed our .details container
    if (!panel || !panel.classList.contains('details')) return;

    // Initialize: collapse panels by setting aria-expanded to false and hiding the panel
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;

    // Toggle event listener
    btn.addEventListener('click', () => {
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';

      // Toggle states
      btn.setAttribute('aria-expanded', String(!isExpanded));
      panel.hidden = isExpanded;
    });
  });
});

